import SwiftUI

/// A list read from its operation a page at a time, sorted, searched and
/// filtered by the service, with its row actions, each offered while its
/// rule holds for the row and its permission is held: one runs an operation
/// on the row, and one opens a page with its route filled from the row.
public struct ListPage: View {
    let schema: ListPageSchema
    /// The page's route parameters; a list takes none.
    let parameters: [String: String]
    /// The routes the page's actions lead to, by the page each names.
    let routes: [String: Routes.Make]
    @Environment(Router.self) private var router
    @AppStorage(Strings.languageKey) private var language = Strings.languages[0]
    @State private var page = 1
    @State private var pageSize: Int
    @State private var sort: (field: String, descending: Bool)?
    @State private var search = ""
    @State private var filters: [String: String] = [:]
    @State private var shown: Set<String>
    @State private var reload = 0
    @State private var rows: [Fields] = []
    @State private var totalItems = 0
    @State private var loading = true
    @State private var failed: String?
    @State private var message: String?
    @State private var confirming: Confirming?
    @State private var reason = ""
    @State private var running = false

    public init(schema: ListPageSchema, parameters: [String: String], routes: [String: Routes.Make]) {
        self.schema = schema
        self.parameters = parameters
        self.routes = routes
        _pageSize = State(initialValue: schema.pageSize)
        _shown = State(initialValue: Set(schema.columns.map(\.field)))
    }

    var columns: [ColumnSchema] { schema.columns.filter { shown.contains($0.field) } }

    /// The query the service reads: the filters, the search, the sort and the page.
    var query: [URLQueryItem] {
        var items: [URLQueryItem] = []
        for filter in schema.filters {
            if let value = filters[filter.field], !value.isEmpty {
                items.append(URLQueryItem(name: filter.query, value: value))
            }
        }
        if !search.isEmpty {
            items.append(URLQueryItem(name: schema.wire.search, value: search))
        }
        if let sort {
            items.append(URLQueryItem(name: schema.wire.sort, value: (sort.descending ? "-" : "") + sort.field))
        }
        items.append(URLQueryItem(name: schema.wire.page, value: String(page)))
        items.append(URLQueryItem(name: schema.wire.pageSize, value: String(pageSize)))
        return items
    }

    var filtered: Bool { schema.filters.contains { !(filters[$0.field] ?? "").isEmpty } || !search.isEmpty }

    public var body: some View {
        let texts = Strings.texts(language)
        List {
            if let failed {
                Text(failed).foregroundStyle(.red)
            }
            if !schema.filters.isEmpty {
                Section(say(texts, "screens.filter")) {
                    ForEach(schema.filters, id: \.field) { filter in
                        filterControl(filter, texts)
                    }
                }
            }
            Section {
                ForEach(Array(rows.enumerated()), id: \.offset) { _, row in
                    rowView(row, texts)
                }
                if loading {
                    ProgressView(say(texts, "screens.loading"))
                } else if let message {
                    Text(message).foregroundStyle(.secondary)
                }
            } footer: {
                HStack {
                    Button(say(texts, "screens.back")) { page -= 1 }.disabled(page <= 1)
                    Spacer()
                    Text("\(page) / \(max(1, Int((Double(totalItems) / Double(max(1, pageSize))).rounded(.up))))")
                    Spacer()
                    Button(say(texts, "screens.next")) { page += 1 }.disabled(page * pageSize >= totalItems)
                }
            }
        }
        .searchable(text: $search, prompt: say(texts, "screens.search"))
        .refreshable { reload += 1 }
        .navigationTitle(say(texts, schema.title))
        .toolbar {
            ToolbarItem {
                Menu(say(texts, "screens.actions")) {
                    ForEach(schema.actions.filter { Actions.holds($0.permission) }, id: \.navigate) { action in
                        if let make = routes[action.navigate] {
                            Button(say(texts, action.label)) { router.go(to: make([:])) }
                        }
                    }
                    ForEach(schema.columns, id: \.field) { column in
                        Toggle(say(texts, column.title), isOn: Binding(get: { shown.contains(column.field) }, set: { on in
                            if on { shown.insert(column.field) } else { shown.remove(column.field) }
                        }))
                    }
                    Picker(say(texts, "screens.columns"), selection: $pageSize) {
                        ForEach(schema.pageSizes, id: \.self) { size in
                            Text(String(size)).tag(size)
                        }
                    }
                    Button(say(texts, "screens.refresh")) { reload += 1 }
                }
            }
        }
        .task(id: "\(query)#\(reload)") { await read(texts) }
        .onChange(of: search) { page = 1 }
        .onChange(of: pageSize) { page = 1 }
        .confirming($confirming, reason: $reason, texts: texts, running: running) { confirming in
            Task { await run(confirming.action, confirming.record, texts) }
        }
        .overlay(alignment: .top) { NoticeView() }
    }

    @ViewBuilder private func filterControl(_ filter: FilterSchema, _ texts: Texts) -> some View {
        let binding = Binding(get: { filters[filter.field] ?? "" }, set: { filters[filter.field] = $0; page = 1 })
        if let options = filter.options {
            Picker(say(texts, filter.title), selection: binding) {
                Text(say(texts, "screens.any")).tag("")
                ForEach(options, id: \.self) { option in
                    Text(option).tag(option)
                }
            }
        } else if filter.date == true {
            DateField(label: say(texts, filter.title), value: binding)
        } else {
            TextField(say(texts, filter.title), text: binding)
        }
    }

    @ViewBuilder private func rowView(_ row: Fields, _ texts: Texts) -> some View {
        let offered = schema.rowActions.filter { Actions.offered($0, row) }
        let cells = VStack(alignment: .leading, spacing: 2) {
            ForEach(Array(columns.enumerated()), id: \.offset) { at, column in
                if at == 0 {
                    Text(Rows.shown(row[column.field], texts)).font(.headline)
                } else {
                    LabeledContent(say(texts, column.title), value: Rows.shown(row[column.field], texts)).font(.subheadline)
                }
            }
        }
        Group {
            if let select = schema.select, let make = routes[select.navigate] {
                NavigationLink(value: make(Dictionary(uniqueKeysWithValues: select.with.map { ($0.key, row[$0.value]?.text ?? "") }))) { cells }
            } else {
                cells
            }
        }
        .contextMenu {
            ForEach(offered, id: \.label) { action in
                actionButton(action, row, texts)
            }
        }
        .swipeActions(edge: .trailing) {
            ForEach(offered, id: \.label) { action in
                actionButton(action, row, texts)
            }
        }
        .sortable(by: schema.columns.filter(\.sortable), sort: $sort, texts: texts, page: $page)
    }

    @ViewBuilder private func actionButton(_ action: RowActionSchema, _ row: Fields, _ texts: Texts) -> some View {
        if action.navigate != nil {
            Button(say(texts, action.label)) {
                if let route = Actions.route(action, row, routes) {
                    router.go(to: route)
                }
            }
        } else {
            Button(say(texts, action.label)) {
                reason = ""
                if action.confirm == nil {
                    Task { await run(action, row, texts) }
                } else {
                    confirming = Confirming(action: action, record: row)
                }
            }
        }
    }

    @MainActor
    private func read(_ texts: Texts) async {
        loading = true
        defer { loading = false }
        do {
            let answer = try await Service.send("GET", schema.source.path, parameters: parameters, query: query)
            guard answer.ok, case .array(let items)? = answer.body?[schema.wire.items] else {
                let refusal = Actions.refusal(schema.failed, answer.status)
                rows = []
                totalItems = 0
                message = say(texts, refusal?.message ?? "screens.failed")
                return
            }
            let totalPages = Int(answer.body?[schema.wire.totalPages]?.text ?? "") ?? 0
            if items.isEmpty, page > 1, totalPages > 0, page > totalPages {
                page = totalPages // the page asked for is past the last
                return
            }
            rows = items.map(\.members)
            totalItems = Int(answer.body?[schema.wire.totalItems]?.text ?? "") ?? 0
            message = rows.isEmpty ? say(texts, filtered ? schema.filteredEmpty : schema.empty) : nil
        } catch {
            rows = []
            totalItems = 0
            message = say(texts, "screens.failed")
        }
    }

    @MainActor
    private func run(_ action: RowActionSchema, _ row: Fields, _ texts: Texts) async {
        if action.reason != nil, reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return
        }
        running = true
        let refused = await Actions.run(action, row, reason: reason, texts)
        running = false
        confirming = nil
        reason = ""
        if let refused {
            failed = refused
            return
        }
        failed = nil
        if let message = action.message {
            router.leave(say(texts, message), at: nil)
        }
        reload += 1
    }
}

/// The sort a list offers: a picker of its sortable columns in the toolbar.
private struct Sortable: ViewModifier {
    let columns: [ColumnSchema]
    @Binding var sort: (field: String, descending: Bool)?
    let texts: Texts
    @Binding var page: Int

    func body(content: Content) -> some View {
        content.toolbar {
            if !columns.isEmpty {
                ToolbarItem {
                    Menu(say(texts, "screens.columns") + " ↕") {
                        ForEach(columns, id: \.field) { column in
                            Button(say(texts, column.title) + (sort?.field == column.field ? (sort?.descending == true ? " ↓" : " ↑") : "")) {
                                if sort?.field != column.field {
                                    sort = (column.field, false)
                                } else if sort?.descending == true {
                                    sort = nil
                                } else {
                                    sort = (column.field, true)
                                }
                                page = 1
                            }
                        }
                    }
                }
            }
        }
    }
}

private extension View {
    func sortable(by columns: [ColumnSchema], sort: Binding<(field: String, descending: Bool)?>, texts: Texts, page: Binding<Int>) -> some View {
        modifier(Sortable(columns: columns, sort: sort, texts: texts, page: page))
    }
}
